package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ArtLiveExamPrehistoricBank1 {
    private const val T = "ප්‍රාග් ඓතිහාසික හා ආදි චිත්‍ර කලාව (ලොව හා ලංකාව)"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("ප්‍රංශයේ පිහිටි ලෝක ප්‍රකට ප්‍රාග් ඓතිහාසික ගුහා චිත්‍ර හමුවන ස්ථානය කුමක්ද?", "ලැස්කෝ ගුහාව", "අජන්තා ගුහාව", "සීගිරි ගුහාව", "එල්ලෝරා ගුහාව", "දකුණු ප්‍රංශයේ ලැස්කෝ (Lascaux) ගුහාවේ වසර 17,000ක් පමණ පැරණි සත්ව චිත්‍ර හමුවේ."),
        q("උතුරු ස්පාඤ්ඤයේ පිහිටි ඇල්ටමීරා ගුහාවේ වහලයෙහි බහුලව ඇඳ ඇති සත්ව රූපය කුමක්ද?", "බයිසන් ගවයා", "වැලි මුවා", "මොනරා", "කිඹුලා", "ස්පාඤ්ඤයේ ඇල්ටමීරා ගුහාවේ චලනශීලී බයිසන් ගව රූප විශේෂයෙන් ප්‍රකටය."),
        q("වසර 30,000කට වඩා පැරණි ප්‍රංශයේ පිහිටි සුප්‍රකට ගුහා චිත්‍ර පද්ධතිය කුමක්ද?", "ෂෝවේ ගුහාව", "බාදාමි ගුහාව", "තන්තිරිමලේ ගුහාව", "බාග් ගුහාව", "ප්‍රංශයේ ෂෝවේ (Chauvet) ගුහාව පැරණිතම පුරාශිලා යුගයේ සිතුවම් සඳහා ප්‍රසිද්ධය."),
        q("ඉන්දියාවේ මධ්‍ය ප්‍රදේශ්හි පිහිටි ප්‍රාග් ඓතිහාසික ගුහා චිත්‍ර හමුවන ලෝක උරුම අඩවිය කුමක්ද?", "භිම්බෙට්කා ලෙන්", "සාරානාත් ලෙන්", "හම්පි ලෙන්", "මහාබලිපුරම් ලෙන්", "භිම්බෙට්කා (Bhimbetka) ගල් ලෙන්වල ඉන්දියාවේ පැරණිතම ගුහා චිත්‍ර දක්නට ලැබේ."),
        q("ලැස්කෝ ගුහාව පළමුවරට නවීන ලෝකයට අනාවරණය වූයේ කුමන වර්ෂයේදීද?", "1940 වර්ෂයේදී", "1879 වර්ෂයේදී", "1905 වර්ෂයේදී", "1968 වර්ෂයේදී", "1940 දී ප්‍රංශයේ යෞවනයන් සිව්දෙනෙකු අතින් අහම්බෙන් ලැස්කෝ ගුහාව සොයා ගැනිණි."),
        q("ඇල්ටමීරා ගුහා චිත්‍ර 1879 දී සොයා ගනු ලැබුවේ කවුරුන් විසින්ද?", "මර්සෙලිනෝ ඩි සෞටුවෝලා සහ දියණිය", "හෙන්රි මැටිස් සහ පිකාසෝ", "ආතර් එවන්ස් සහ කාටර්", "ලියොනාඩෝ සහ වාසාරි", "ස්පාඤ්ඤ ජාතික මර්සෙලිනෝ සෞටුවෝලා හා ඔහුගේ දියණිය ඇල්ටමීරා චිත්‍ර සොයා ගත්හ."),
        q("ප්‍රාග් ඓතිහාසික කලාකරුවන් කළු වර්ණය සෑදීමට බහුලව යොදා ගත් ද්‍රව්‍යය කුමක්ද?", "අඟුරු සහ මැංගනීස් ඔක්සයිඩ්", "නිල් මැණික් සහ ලාපිස් ලාසුලි", "තඹ ඔක්සයිඩ් සහ ඊයම්", "වෙඩි ලුණු සහ කහ මදය", "දැව අඟුරු හා මැංගනීස් ඔක්සයිඩ් කුඩු කර සත්ව තෙල් සමඟ මිශ්‍ර කර කළු පැහැය සාදා ගත්හ."),
        q("ආදි ගුහා සිතුවම්වල රතු සහ දුඹුරු වර්ණ නිපදවීමට භාවිත කළ ප්‍රධාන ඛනිජය කුමක්ද?", "ගුරුගල් හෙවත් යකඩ ඔක්සයිඩ්", "රසදිය හෙවත් සින්ක්", "මයිකා හෙවත් තලාතු මිනිරන්", "හුණුගල් හෙවත් ජිප්සම්", "රතු ගුරුගල් (Red Ochre / Hematite) ආදි මානවයාගේ ප්‍රධානතම රතු වර්ණකය විය."),
        q("ගුහා චිත්‍රවල වර්ණක ගල් බිත්තියට ඇලවීම සඳහා මාධ්‍යකය ලෙස යොදා ගත්තේ කුමක්ද?", "සත්ව තෙල්, ලේ හා ශාක යුෂ", "කෘත්‍රිම ඇක්‍රිලික් මාධ්‍ය", "ටර්පන්ටයින් සහ තිනර්", "විනිගර් සහ රසදිය", "ඛනිජ කුඩු සත්ව මේදය, මැලියම් හෝ ශාක යුෂ සමඟ අඹරා භාවිත කෙරිණි."),
        q("ආදි ගුහා චිත්‍රවල ඇඳි අත තබා පිටතින් වර්ණ පිඹීමේ තාක්ෂණය හැඳින්වෙන්නේ කෙසේද?", "ස්ටෙන්සිල් හෙවත් අච්චු ක්‍රමය", "ටෙම්පෙරා හෙවත් බිත්තර ක්‍රමය", "එන්කෝස්ටික් හෙවත් ඉටි ක්‍රමය", "ස්ෆුමාටෝ හෙවත් දුමාර ක්‍රමය", "බටයක් හරහා වර්ණ කුඩු පිඹ අතේ සටහන ගල මත ඉතිරි කිරීම මුල්කාලීන ස්ටෙන්සිල් ක්‍රමයකි."),
        q("පුරාශිලා යුගයේ ආදි මානවයා විසින් සත්ව රූප ඇඳීමේ ප්‍රධානතම විශ්වාසමය අරමුණ කුමක්ද?", "දඩයම සාර්ථක කර ගැනීමේ අභිචාරය", "වෙළඳ ප්‍රචාරණ කටයුතු", "රාජකීය ආඥා ප්‍රකාශ කිරීම", "අධ්‍යාපන පෙළපොත් සැකසීම", "දඩයම් මායා විශ්වාසය (Hunting Magic) අනුව චිත්‍රණයෙන් දඩයම පහසු වෙතැයි සැලකිණි."),
        q("ඕස්ට්‍රියාවෙන් හමු වූ වසර 25,000ක් පැරණි ප්‍රාග් ඓතිහාසික මූර්තිය කුමක්ද?", "විලෙන්ඩෝෆ්හි වීනස් රුව", "සාරානාත්හි සිංහ කුළුණ", "මිලෝහි වීනස් රුව", "නෙෆර්ටිටි උඩුකය රුව", "හුණුගලින් නෙළූ කුඩා කාන්තා රුවක් වන විලෙන්ඩෝෆ්හි වීනස් සශ්‍රීකත්වයේ සංකේතයකි."),
        q("විලෙන්ඩෝෆ්හි වීනස් ප්‍රතිමාව මගින් සංකේතවත් කරන ප්‍රධාන තේමාව කුමක්ද?", "සශ්‍රීකත්වය හා මාතෘත්වය", "යුද ජයග්‍රහණය හා බලය", "සමුද්‍ර වෙළඳාම හා නාවික බලය", "තාරකා විද්‍යාව හා ගණිතය", "පුළුල් ශරීර ලක්ෂණ සහිත මෙම කුඩා ප්‍රතිමාව සශ්‍රීකත්වය නිරූපණය කරයි."),
        q("ප්‍රාග් ඓතිහාසික යුගය ප්‍රධාන කාල පරිච්ඡේද තුනකට බෙදනු ලබන්නේ කුමක් පදනම් කරගෙනද?", "භාවිත කළ ගල් ආයුධවල ස්වභාවය", "රචනා කළ ලිඛිත ග්‍රන්ථ ප්‍රමාණය", "ඉදිකළ මහා ප්‍රාසාද ගණන", "නිපදවූ ලෝහ කාසි වර්ග", "පුරාශිලා, මධ්‍යශිලා සහ නවශිලා යනුවෙන් ගල් ආයුධ තාක්ෂණය අනුව යුග බෙදා ඇත."),
        q("පුරාශිලා (Paleolithic) යුගයේ චිත්‍රවල බොහෝ විට නිරූපණය වී ඇති ශෛලිය කුමක්ද?", "සත්ව රූපවල ස්වභාවික හා ජීවමාන චලනය", "සම්පූර්ණ වියුක්ත රේඛා සැලසුම්", "ඒකලක්ෂ්‍ය රේඛීය දෘෂ්ටිකෝණ", "රන් ආලේපිත අලංකාර මල්කම්", "දඩයම් කළ සතුන්ගේ මාංශ පේශි හා චලනය ඉතා ස්වභාවිකව ගුහා චිත්‍රවල දැක්වේ."),
        q("නවශිලා (Neolithic) යුගය ආරම්භ වීමත් සමඟ චිත්‍ර කලාවේ ඇති වූ ප්‍රධාන වෙනස්කම කුමක්ද?", "සරල ජ්‍යාමිතික රටා හා මැටි බඳුන් මෝස්තර බිහිවීම", "තෙල් සායම් කැන්වස් චිත්‍ර බිහිවීම", "වීදුරු මූර්ති කර්මාන්තය බිහිවීම", "මුද්‍රණ යන්ත්‍ර චිත්‍ර බිහිවීම", "කෘෂිකර්මය හා ස්ථාවර ජනාවාස ඇරඹීමත් සමඟ මැටි බඳුන් මත ජ්‍යාමිතික රටා ඇඳීම වර්ධනය විය."),
        q("එංගලන්තයේ පිහිටි නවශිලා යුගයට අයත් ප්‍රකට මහා ශිලා ස්මාරකය කුමක්ද?", "ස්ටෝන්හෙන්ජ් ශිලා වළල්ල", "කොලෝසියම් රංග පීඨය", "පාතෙනන් දෙවොල", "ගීසා මහා පිරමීඩය", "විශාල ගල් කුළුණු වෘත්තාකාරව පිහිටුවා සෑදූ ස්ටෝන්හෙන්ජ් නවශිලා යුගයේ විශිෂ්ට නිර්මාණයකි."),
        q("ලැස්කෝ ගුහාවේ 'ගොනුන්ගේ ශාලාව' (Hall of Bulls) හි ඇඳ ඇති සත්ව රූපයක දිග කොපමණ පමණ වේද?", "මීටර් පහක් පමණ දිගය", "සෙන්ටිමීටර පහක් පමණ දිගය", "මීටර් පනහක් පමණ දිගය", "මිලිමීටර දහයක් පමණ දිගය", "ගොනුන්ගේ ශාලාවේ ඇති ප්‍රධාන ගව රූපයක් මීටර් 5කට ආසන්න දැවැන්ත ප්‍රමාණයෙන් යුක්තය."),
        q("ආදි ගුහා කලාකරුවා ගල් බිත්තියේ ස්වභාවික නෙරීම් හා වක්‍රතා ප්‍රයෝජනයට ගත්තේ කුමක් සඳහාද?", "සත්ව රූපවලට ත්‍රිමාණ බවක් ලබා දීමට", "ලේඛන සටහන් අකුරු කෙටීමට", "ජල නළ පද්ධති සවි කිරීමට", "ලී දොර උළුවහු තැබීමට", "ඇල්ටමීරා ගුහාවේ පර්වතයේ නෙරා ඇති කොටස් බයිසන් ගවයින්ගේ ශරීර හැඩය මතු කිරීමට යොදා ගති."),
        q("ගුහා සිතුවම්කරණයේදී වර්ණ ආලේප කිරීමට භාවිත කළ ආදි පින්සල් නිපදවා ගත්තේ කුමකින්ද?", "සත්ව ලොම්, කෙඳි සහ තැළූ කෝටු කැබලි", "නයිලෝන් කෙඳි සහ ඇලුමිනියම්", "ප්ලාස්ටික් කූරු සහ ස්පොන්ජි", "වානේ තල සහ තඹ කම්බි", "අතු කැබලි තලා පොඩි කිරීමෙන් හා සත්ව රෝම බැඳීමෙන් ආදි පින්සල් සකස් කර ගත්හ."),
        q("ඇල්ටමීරා ගුහාව පිහිටි යුරෝපීය රට කුමක්ද?", "ස්පාඤ්ඤය", "ඉතාලිය", "ග්‍රීසිය", "ජර්මනිය", "ඇල්ටමීරා ගුහාව උතුරු ස්පාඤ්ඤයේ කැන්ටබ්‍රියා ප්‍රදේශයේ පිහිටා ඇත."),
        q("ලැස්කෝ ගුහා සිතුවම් හි රේඛා සටහන් කිරීමෙන් පසු අභ්‍යන්තරය පිරවීමට භාවිත කළ ක්‍රමය කුමක්ද?", "ගුරුගල් හා අඟුරු සෙවණැලි ආලේපනය", "සිමෙන්ති බදාම තට්ටු ඇතිරීම", "රන් තහඩු කපා ඇලවීම", "වීදුරු කැබලි ඔබ්බවා සැකසීම", "රතු හා කහ ගුරුගල් මගින් වර්ණ ගැන්වීමෙන් සත්ව ශරීරවල පරිමාව දක්වන ලදී."),
        q("ගුහා බිත්තියක පර්වත මතුපිට සූරා හෝ හාරා රූප ඇඳීම හඳුන්වනු ලබන්නේ කුමන නමකින්ද?", "පෙට්‍රොග්ලිෆ් හෙවත් ශිලා කෙටුම්", "ෆ්‍රෙස්කෝ බුවොනෝ සිතුවම්", "මොසැයික් පිඟන් කැටයම්", "ඉම්පැස්ටෝ තෙල් සායම්", "ගල මතුපිට තියුණු ගල් ආයුධවලින් හාරා කෙටූ රූප පෙට්‍රොග්ලිෆ් (Petroglyphs) ලෙස හැඳින්වේ."),
        q("ප්‍රංශ-කැන්ටබ්‍රියන් කලාපයේ ප්‍රාග් ඓතිහාසික ගුහා චිත්‍රවල බහුලව දක්නට ලැබෙන සත්ව කාණ්ඩය කුමක්ද?", "අශ්වයන්, ගවයන්, මුවන් සහ මැමත්", "සිංහයන්, පෙන්ගුයින් සහ කැන්ගරු", "මොනරුන්, හංසයන් සහ ගිරවුන්", "ඩොල්ෆින්, තල්මසුන් සහ මෝරුන්", "එම කාලයේ යුරෝපයේ ජීවත් වූ විශාල ශාකභක්ෂක සතුන් බහුලව චිත්‍රණය කර තිබේ."),
        q("ගුහා සිතුවම්වල මිනිස් රූප ඇඳීමේදී බොහෝ විට අනුගමනය කර ඇති ස්වරූපය කුමක්ද?", "සරල කූරු රූප හෙවත් රේඛාමය ආකාරය", "ඉතා සියුම් මුහුණු ලක්ෂණ සහිත රූප", "පූර්ණ වර්ණ ඡායාරූප ස්වරූපය", "පංච තාල ප්‍රමාණ විද්‍යා රූප", "සතුන් ඉතා ස්වභාවිකව ඇන්දද මිනිස් රූප ඉතා සරල කූරු රූප ලෙස ඇඳීම විශේෂත්වයකි."),
        q("ලැස්කෝ ගුහාව මහජනයාට නැරඹීමට විවෘත කිරීමෙන් පසු 1963 දී වසා දැමීමට සිදුවූයේ ඇයි?", "ප්‍රේක්ෂකයන්ගේ හුස්ම හා දිලීර නිසා චිත්‍ර විනාශ වීමෙන්", "භූමිකම්පාවකින් ගුහාව කඩා වැටීමෙන්", "නව මහා මාර්ගයක් ඉදි කිරීම නිසා", "ගංවතුරෙන් ගුහාව සම්පූර්ණයෙන් යට වීමෙන්", "කාබන් ඩයොක්සයිඩ්, ආර්ද්‍රතාව හා හරිත ඇල්ගී වර්ධනය වීම නිසා මුල් ගුහාව වසා දමා අනුරුවක් තනන ලදී."),
        q("දකුණු අප්‍රිකාවේ සැන් (San) ගෝත්‍රික ජනතාවගේ පැරණි ගුහා සිතුවම්වල ප්‍රධාන තේමාව කුමක්ද?", "දඩයම සහ ආගමික නැටුම් අවස්ථා", "නෞකා ගමනාගමනය සහ මුහුදු යුද්ධ", "නාගරික මාලිගා සහ මහා මාර්ග", "රජවරුන්ගේ අභිෂේක මංගල්‍ය", "සැන් ගෝත්‍රික ගල් ලෙන් චිත්‍රවල ධ්‍යානගත නැටුම් හා සත්ව දඩයම් දර්ශන විශිෂ්ට ලෙස දැක්වේ."),
        q("ඕස්ට්‍රේලියාවේ ආදිවාසීන්ගේ (Aboriginal) සාම්ප්‍රදායික ගල් චිත්‍රවල විශේෂ ලක්ෂණය කුමක්ද?", "X-රේ ආකාරයෙන් අභ්‍යන්තර අවයව දැක්වීම", "ත්‍රිමාණ තෙල් සායම් සෙවණැලි යෙදීම", "චීන තීන්ත මගින් කඳු වැටි ඇඳීම", "රන් කඩදාසි මත රූප කැපීම", "සතුන්ගේ සිරුර තුළ ඇටකටු හා අභ්‍යන්තර අවයව පෙනෙන සේ ඇඳීම X-ray style නම් වේ."),
        q("ආදි මානවයා විසින් චිත්‍රණය සඳහා සුදු පැහැය ලබා ගත් ස්වභාවික ද්‍රව්‍යය කුමක්ද?", "කයෝලින් මැටි හෙවත් කිරිමැටි සහ හුණු", "සින්ක් ඔක්සයිඩ් සහ ටයිටේනියම්", "සුදු පැහැති ඉටිපන්දම් දියර", "ඇල්බියුමින් සහ රසදිය ලවණ", "සුදු කිරිමැටි සහ හුණු ජලය හෝ තෙල් සමඟ මිශ්‍ර කර සුදු පැහැය සාදා ගන්නා ලදී."),
        q("මැටි පිළිස්සීමේ කලාව හෙවත් කුඹල් කර්මාන්තය මුලින්ම ප්‍රචලිත වූ ප්‍රාග් ඓතිහාසික යුගය කුමක්ද?", "නවශිලා යුගය", "මුල් පුරාශිලා යුගය", "හිම යුගයේ ආරම්භය", "ඩයිනෝසෝර යුගය", "ගොවිතැන සමඟ ධාන්‍ය ගබඩා කිරීමට නවශිලා යුගයේදී මැටි බඳුන් පිළිස්සීම ආරම්භ විය."),
        q("ඉන්දියාවේ භිම්බෙට්කා ගුහා සිතුවම් මුලින්ම 1957 දී සොයා ගනු ලැබූ ඉන්දීය පුරාවිද්‍යාඥයා කවුද?", "විෂ්ණු ශ්‍රීධර් වකන්කර්", "සෙනරත් පරණවිතාන", "ජෝන් මාෂල්", "ඇලෙක්සැන්ඩර් කනිංහැම්", "වි. ශ්‍රී. වකන්කර් මහතා විසින් මධ්‍ය ප්‍රදේශ්හි භිම්බෙට්කා ගල් ලෙන් සිතුවම් අනාවරණය කෙරිණි."),
        q("ආදි ගුහා කලාකරුවන් රාත්‍රී හෝ අඳුරු ගුහා ඇතුළත ආලෝකය ලබා ගත්තේ කෙසේද?", "ගල් පහන්වල සත්ව තෙල් දැල්වීමෙන්", "විදුලි පන්දම් භාවිත කිරීමෙන්", "පරාවර්තක කණ්ණාඩි තැබීමෙන්", "රසායනික ප්‍රතිදීප්ත දියරවලින්", "කුඩා ගල් කුහරවල සත්ව මේදය හා පාසි තිර දමා පහන් දල්වා ගුහා තුළ ආලෝකය ලබා ගත්හ."),
        q("පුරාශිලා යුගයේ චිත්‍රවල දක්නට ලැබෙන 'බහු රූප උපරිපතනය' (Superimposition) යනු කුමක්ද?", "පැරණි රූප මත නැවත අලුත් රූප ඇඳීම", "වීදුරු තහඩු මත රූප ඇඳීම", "සතුන්ගේ සිරුරේ තිත් රටා තැබීම", "එකම රූපය දර්පණ මෙන් පිළිබිඹු කිරීම", "එකම පූජනීය ගුහා බිත්තියේ පරම්පරා ගණනාවක් පුරා රූප මත රූප ඇඳීම මෙලෙස හැඳින්වේ."),
        q("ආදි මානවයා විසින් කහ වර්ණය නිපදවා ගත් ප්‍රධාන ස්වභාවික ඛනිජ වර්ගය කුමක්ද?", "කහ ගුරුගල් හෙවත් ලිමොනයිට්", "කැඩ්මියම් කහ කෘත්‍රිම කුඩු", "ගම්බෝජ් හෙවත් ශාක කිරි පමණි", "රන් කුඩු හා සින්ක් සල්ෆේට්", "කහ ගුරුගල් (Yellow Ochre / Limonite) යනු ගුහා චිත්‍රවල බහුලව භාවිත කළ කහ වර්ණකයයි."),
        q("නවශිලා යුගයේ නිර්මාණය වූ මැටි බඳුන්වල දක්නට ලැබෙන සැරසිලි මෝස්තර මොනවාද?", "සමාන්තර රේඛා, ත්‍රිකෝණ සහ වළලු", "මහනුවර ලියවැල් සහ පලාපෙති", "යුරෝපීය ඇකැන්තස් කොළ රටා", "ඉස්ලාමීය අරාබි අක්ෂර මෝස්තර", "රේඛා, කතිර, ත්‍රිකෝණ සහ රැලි වැනි සරල ජ්‍යාමිතික රටා මැටි බඳුන්වල දැකිය හැක."),
        q("ෂෝවේ ගුහා චිත්‍රවල නිරූපණය කර ඇති කළු රේඛාමය රයිනෝසිරස් රූපවල ඇති කලාත්මක විශේෂත්වය කුමක්ද?", "සිරස් හා චලන අවස්ථා පෙන්වන බහු රේඛා", "රතු තීන්තවලින් වට කළ රාමු", "සමමිතික මල් මෝස්තර පසුබිම", "පූර්ණ වශයෙන් සුදු පැහැ ගැන්වීම", "හිස හා අං කිහිප වරක් ඇඳ චලන මායාවක් මවා තිබීම ෂෝවේ ගුහාවේ විශේෂත්වයකි."),
        q("ප්‍රාග් ඓතිහාසික කලා කෘතිවල වයස නිර්ණය කිරීම සඳහා විද්‍යාඥයන් යොදා ගන්නා ප්‍රධාන ක්‍රමය කුමක්ද?", "රේඩියෝ කාබන් කාල නිර්ණ ක්‍රමය", "ගසක වර්ධක වළලු ගණන් කිරීම", "භූ ගෝලීය සිතියම් සැසඳීම", "වර්ණකවල බර කිරා බැලීම", "අඟුරු වර්ණකවල අඩංගු කාබන්-14 සමස්ථානිකය මැනීමෙන් චිත්‍රවල වයස නිර්ණය කෙරේ."),
        q("පුරාශිලා ගුහා චිත්‍රවල 'ට්විස්ටඩ් පර්ස්පෙක්ටිව්' (Twisted Perspective) ලෙස හැඳින්වෙන්නේ කුමක්ද?", "සිරුර පැතිකඩින් හා අං ඉදිරියෙන් දැක්වීම", "සියලු රූප උඩු යටිකුරු කර ඇඳීම", "කුඩා රූප පසුබිමෙන් විශාලව ඇඳීම", "රූප සම්පූර්ණයෙන් කැඩපතකින් බලා ඇඳීම", "සත්වයාගේ සිරුර පැත්තෙන් පෙන්වා අං යුගලය ඉදිරිපසින් පෙනෙන සේ ඇඳීම මෙහි ලක්ෂණයයි."),
        q("ආදි මානවයා විසින් කුඩා සත්ව අස්ථි හා ඇත් දත් මත කැටයම් කළ සුප්‍රකට කලා නිර්මාණයක් වන්නේ කුමක්ද?", "ලා මැඩ්ලේන්හි පිහිනන පිනිමුවා", "මිසරයේ ස්පින්ක්ස් මූර්තිය", "ග්‍රීසියේ කවපෙත්ත විසි කරන්නා", "ඉන්දියාවේ නටරාජ ලෝකඩ රුව", "ඇත්දත් හෝ අං මත කැටයම් කළ පිනිමුවන්ගේ රූප පුරාශිලා කැටයම් කලාවේ උසස් නිදසුන්ය."),
        q("බ්‍රසල්ස්හි රේන්ඩියර් යුගය හෙවත් ප්‍රංශයේ කුමන යුගයක ගුහා චිත්‍ර කලාව උච්චතම අවස්ථාවට පත්වීද?", "මැග්ඩලීනියන් යුගය", "ක්‍රේටේසියස් යුගය", "හෙලනිස්තික යුගය", "වික්ටෝරියානු යුගය", "පසු පුරාශිලා මැග්ඩලීනියන් (Magdalenian) යුගයේදී ලැස්කෝ හා ඇල්ටමීරා චිත්‍ර බිහිවිය."),
        q("භිම්බෙට්කා ගුහා චිත්‍රවල වැඩි වශයෙන් යොදාගෙන ඇති ප්‍රධාන වර්ණ යුගලය කුමක්ද?", "රතු සහ සුදු වර්ණ", "නිල් සහ රන්වන් වර්ණ", "දම් සහ තැඹිලි වර්ණ", "කොළ සහ රිදී වර්ණ", "භිම්බෙට්කා චිත්‍රවල ප්‍රධාන වශයෙන් සුදු පැහැති හුණු හා රතු පැහැති ගුරුගල් භාවිත කර ඇත."),
        q("ප්‍රාග් ඓතිහාසික මූර්ති කලාවේ ඇත්දත් කැටයමක් වන 'ලෝවෙන්මෙන්ෂ්' (Lowenmensch) හෙවත් සිංහ-මිනිස් රුව හමුවූයේ කොහෙන්ද?", "ජර්මනියේ හොහ්ලෙන්ස්ටයින් ගුහාවෙන්", "ශ්‍රී ලංකාවේ බටදොඹලෙනෙන්", "ඊජිප්තුවේ කානක් දෙවොලෙන්", "චීනයේ ටෙරාකොටා නිධියෙන්", "ජර්මනියෙන් හමු වූ සිංහ හිසක් හා මිනිස් සිරුරක් සහිත මෙය පැරණිතම පූජනීය කැටයමකි."),
        q("ගුහා සිතුවම්වල දක්නට ලැබෙන ජ්‍යාමිතික සලකුණු හෙවත් 'එන්ටොප්ටික් සලකුණු' අතරට අයත් වන්නේ මොනවාද?", "තිත්, සිග්සැග් රේඛා හා දැල් රටා", "සිංහල අක්ෂර හා ඉලක්කම්", "මල්මාලා හා ඔටුනු හැඩතල", "පංච තාල පද කැටයම්", "වංගු රේඛා, තිත් පෙළවල් හා ජ්‍යාමිතික හැඩතල ලෝකයේ බොහෝ ගුහා චිත්‍රවල පොදුය."),
        q("ආදි ගුහා කලාවේ 'බාසෙක්-රොක්' හෝ පර්වත මතුපිට ඇඹූ මැටි මූර්ති හමු වූ ප්‍රංශ ගුහාව කුමක්ද?", "ටක් ඩි ඔඩෝබර්ට් ගුහාව", "නොට්‍රඩෑම් දෙව්මැදුර", "ලූවර් ගුහා කුටිය", "වර්සායි ගල් මණ්ඩපය", "ප්‍රංශයේ ටක් ඩි ඔඩෝබර්ට් ගුහාවේ මැටියෙන් අඹන ලද බයිසන් ගව යුගලයක් අදටත් සුරක්ෂිතය."),
        q("ප්‍රාග් ඓතිහාසික කලාවේදී මිනිස් හස්ත සලකුණු (Handprints) බහුලව සටහන් කර තිබීමෙන් හැඟවෙන්නේ කුමක්ද?", "කලාකරුවාගේ අනන්‍යතාව හා සහභාගීත්වය", "ලියුම් හුවමාරු ක්‍රමවේදය", "රජුගේ බදු ගෙවූ රිසිට්පත", "නූතන ඇඟිලි සලකුණු තාක්ෂණය", "අත් සලකුණු තැබීම ආදි මානවයා තම පැවැත්ම හා චාරිත්‍රමය සම්බන්ධය ප්‍රකාශ කළ ක්‍රමයකි."),
        q("ලොව පැරණිතම ගුහා චිත්‍ර කිහිපයක් මෑතකදී ආසියානු කලාපයේ කුමන දූපතකින් සොයා ගෙන තිබේද?", "ඉන්දුනීසියාවේ සුලවේසි දූපත", "ජපානයේ හොක්කයිඩෝ දූපත", "මාලදිවයිනේ මාලේ දූපත", "මැඩගස්කර දූපත", "සුලවේසි දූපතේ හුණුගල් ගුහාවලින් වසර 45,000කට වඩා පැරණි ඌරු රූප හමුවී ඇත."),
        q("සහරා කාන්තාරයේ ටැසිලි-න්-අජර් (Tassili n'Ajjer) පර්වත චිත්‍ර මගින් සනාථ වන වැදගත් කරුණ කුමක්ද?", "පැරණි සහරාව සශ්‍රීක තණබිමක්ව පැවති බව", "සහරාවේ විශාල හිම කඳු තිබූ බව", "පිරමීඩ සහරාවේ මුලින් තැනූ බව", "ග්‍රීක නැව් සහරාවේ ගමන් කළ බව", "ජිරාෆ්, හිපෝ හා ගව රංචු දැක්වෙන මෙම චිත්‍ර පුරාණ සහරාව හරිත ප්‍රදේශයක්ව තිබූ බව පෙන්වයි."),
        q("ආදි මානවයා චිත්‍ර ඇඳීමට සඳහා ගල් පුවරුවක් මත වර්ණ ඇඹරීමට යොදා ගත් උපකරණ මොනවාද?", "ඇඹරුම් ගල් සහ සත්ව හිස්කබල් බඳුන්", "විදුලි ඇඹරුම් යන්ත්‍ර", "චීන පිඟන් භාජන", "ලෝහ වංගෙඩි සහ මෝල්ගස්", "ගුරුගල් කුඩු කිරීමට ගල් තැටි හා තෙල් මිශ්‍ර කිරීමට සිප්පි කටු හෝ අස්ථි කෝප්ප භාවිත කළහ."),
        q("පුරාශිලා ගුහා සිතුවම් තුළ කලාතුරකින් දක්නට ලැබෙන 'නිල්' සහ 'කොළ' වර්ණ අඩු වීමට හේතුව කුමක්ද?", "එම වර්ණ දෙන ස්ථායී ඛනිජ සුලබ නොවීම", "නිල් වර්ණය ආගමිකව තහනම් කර තිබීම", "එම වර්ණ දියර වාෂ්ප වී අතුරුදන් වීම", "ආදි මානවයාට වර්ණ අන්ධතාව පැවතීම", "යකඩ ඔක්සයිඩ් හා අඟුරු සුලබ වූ නමුත් නිල් හා කොළ ස්ථායී ඛනිජ වර්ණක දුර්ලභ විය."),
        q("ලැස්කෝ ගුහාවේ 'ෂාෆ්ට් දර්ශනය' (Shaft Scene) නමින් ප්‍රකට චිත්‍රයෙන් දැක්වෙන්නේ කුමක්ද?", "තුවාල වූ බයිසන් ගවයෙකු හා වැටුණු දඩයක්කරු", "ගඟක පිහිනන මුව රංචුවක්", "ගිනි මැලයක් වටා නටන කාන්තාවන්", "මැමත් ඇතෙකු ගස් උගුල්ලන අයුරු", "වැටී සිටින කුරුලු හිසක් ඇති මිනිස් රුවක් හා බයිසන් ගවයෙකු මෙම විරල ආඛ්‍යානමය චිත්‍රයේ වේ."),
        q("දඹුල්ල ආශ්‍රිත ඉබ්බන්කටුව සුසාන භූමිය හා ලංකාවේ පූර්ව ඓතිහාසික කලාව අයත් වන්නේ කුමන සංස්කෘතියටද?", "මහාශිලා හෙවත් යකඩ යුග සංස්කෘතිය", "රෝම සම්භාව්‍ය සංස්කෘතිය", "ගොතික් මධ්‍යකාලීන සංස්කෘතිය", "බැරොක් යුරෝපීය සංස්කෘතිය", "ඉබ්බන්කටුව කාලරක්ත මැටි බඳුන් හා පබළු නිර්මාණ ලංකාවේ මහාශිලා යුගය නියෝජනය කරයි."),
        q("කාලරක්ත මැටි බඳුන් (Black and Red Ware) යනු කුමන ලක්ෂණයකින් යුත් ආදි කලා නිර්මාණද?", "ඇතුළත කළු හා පිටත රතු පැහැ ගැන්වූ මැටි බඳුන්", "තනි කොළ පැහැයෙන් පින්තාරු කළ පිඟන්", "වීදුරු ආලේප කළ චීන ජෝගු", "රන් කැටයම් සහිත ලෝකඩ කළගෙඩි", "පෝරණුවේ ප්‍රතිලෝම දහන ක්‍රමයෙන් ඇතුළත කළු හා පිටත රතු වන සේ මෙම බඳුන් පුළුස්සා ඇත."),
        q("ප්‍රාග් ඓතිහාසික කලා අධ්‍යයනයේදී 'පරිසරය හා මානවයා අතර සබඳතාව' පැහැදිලිව පෙනෙන්නේ කෙසේද?", "වර්ණක හා මෙවලම් සම්පූර්ණයෙන් ස්වභාවික ද්‍රව්‍ය වීමෙන්", "ආනයනික තෙල් සායම් නළ භාවිත කිරීමෙන්", "කර්මාන්තශාලා කැන්වස් රෙදි භාවිතයෙන්", "ලෝහ මුද්‍රණ තහඩු කැපීමෙන්", "ගල්, මැටි, ශාක යුෂ හා සත්ව තෙල් වැනි පරිසරයේ ඇති ද්‍රව්‍ය පමණක් භාවිත කර තිබීමෙන්."),
        q("නවශිලා යුගයේ මැටි බඳුන් මත මෝස්තර යෙදීම සඳහා 'කෝඩ් මාර්ක්ඩ්' (Cord-marked) ක්‍රමයේදී යොදා ගත්තේ කුමක්ද?", "තෙත මැටි මත ලණු හෝ කෙඳි එබීම", "පිළිස්සූ පසු ඇක්‍රිලික් වර්ණ ගෑම", "රන් කම්බි ගිල්වා පෑස්සීම", "අම්ල දියර ඉස කැටයම් කිරීම", "මැටි වියළීමට පෙර ගෙතූ ලණු කැබැල්ලක් මතුපිට තද කර රටා මතු කිරීම පැරණි ක්‍රමයකි."),
        q("ලැස්කෝ හි පිහිනන මුවන් (Swimming Stags) චිත්‍රයේ ඇති විශේෂ කලාත්මක ලක්ෂණය කුමක්ද?", "මුවන්ගේ හිස් පමණක් ගල මත ඇඳ ජලය හැඟවීම", "මුළු ගුහා වහලය නිල් පැහැ ගැන්වීම", "මසුන් දහස් ගණනක් වටේට ඇඳීම", "වක්‍රාකාර කන්නාඩි රාමුවක ඇඳීම", "පර්වතයේ රේඛාවක් ජල මට්ටම ලෙස යොදා ගෙන ඉහළින් මුව හිස් පෙළ ඇඳීමෙන් පිහිනීම පෙන්වා ඇත."),
        q("දකුණු ප්‍රංශයේ පෙක්-මර්ල් (Pech Merle) ගුහාවේ ඇඳ ඇති 'තිත් සහිත අශ්වයන්' චිත්‍රයේ විශේෂත්වය කුමක්ද?", "අශ්ව රූප වටා අත් සලකුණු හා තිත් රටා යෙදීම", "අශ්වයන්ට පියාපත් ඇඳ තිබීම", "අශ්ව රූප ලෝහයෙන් නිමවා තිබීම", "රන් පත්‍ර මත තෙල් සායමින් ඇඳීම", "වෛරම් තිත් සහිත අශ්ව රූප දෙකක් හා අවට ඇති නෙගටිව් අත් සලකුණු මෙහි ප්‍රකටය."),
        q("ප්‍රාග් ඓතිහාසික මූර්තියක් වන 'වීනස් ඔෆ් බ්‍රාසෙම්පෝයි' කුමන ද්‍රව්‍යයෙන් නිර්මාණය කර ඇත්ද?", "මැමත් ඇත්දත්", "රතු කිරිගරුඬ ගල්", "තඹ සහ ටින් ලෝකඩ", "පිළිස්සූ ගඩොල් මැටි", "වසර 25,000ක් පැරණි මෙම කුඩා කාන්තා හිස මැමත් ඇත්දත් කැබැල්ලකින් නෙළා ඇත."),
        q("ආදි ගුහා සිතුවම් බොහෝ විට ගුහා මුවදොරට වඩා අඳුරු ගැඹුරු කුටීරවල ඇඳ තිබීමට හේතුව ලෙස සැලකෙන්නේ කුමක්ද?", "ඒවා අභිචාරමය හා රහසිගත පූජා ස්ථාන වීම", "ගුහා මුවදොරේ ඉඩකඩ සම්පූර්ණයෙන් මදි වීම", "සතුන්ට පෙනීම වැළැක්වීම සඳහා", "වර්ණ වියළීම පමා කිරීම සඳහා", "පූජනීය චාරිත්‍ර හා දඩයම් අභිචාර ඉටු කළ ගැඹුරු කුටීර සඳහා ඒවා නිර්මාණය වූ බව පිළිගැනේ."),
        q("භිම්බෙට්කා ගුහා සිතුවම්වල 'සත්ව චර්යාව' නිරූපණය වී ඇති ආකාරය කෙබඳුද?", "දුවන, පනින සහ දඩයම් කරන චලන අවස්ථා ලෙස", "මියගොස් සිටින නිශ්චල රූප ලෙස පමණි", "රේඛීය වගු සටහන් ආකාරයෙන්", "ලියවැල් ඇතුළත සැඟවුණු හැඩතල ලෙස", "සත්ව රූපවල චලනය හා මිනිසුන් සමූහ දඩයම් කරන අයුරු ජවසම්පන්නව දක්වා ඇත."),
        q("ආදි කලා නිර්මාණ අතර පවතින 'පෝටබල් ආට්' (Mobiliary/Portable Art) යනු මොනවාද?", "රැගෙන යා හැකි කුඩා ප්‍රතිමා හා අස්ථි කැටයම්", "විශාල පර්වත මත ඇඳි ගුහා සිතුවම්", "මීටර් ගණන් උස මහා ශිලා කුළුණු", "කැන්වස් මත ඇඳි විශාල තෙල් සායම් චිත්‍ර", "කුඩා වීනස් රූප හා කැටයම් කළ මෙවලම් වැනි එහා මෙහා ගෙන යා හැකි කලා කෘති මෙනමින් හැඳින්වේ."),
        q("පුරාශිලා මානවයා විසින් සිය ශරීරය සරසා ගැනීමට භාවිත කළ මුල්කාලීන ආභරණ මොනවාද?", "සිප්පි කටු, සත්ව දත් සහ සිදුරු කළ ඇටකටු", "වජ්‍ර, මුතු සහ රන් මාල", "ප්ලාස්ටික් සහ වීදුරු වළලු", "මුද්‍රිත රෙදි පටි සහ බොත්තම්", "සිදුරු කළ සත්ව දත් හා සිප්පි කටු නූල්වල ඇමිණීමෙන් ආදි ආභරණ තනා ගත්හ."),
        q("ඉරානය, පැරණි මෙසපොතේමියාව වැනි කලාපවල නවශිලා යුගයේ මැටි බඳුන්වල දැකිය හැකි ප්‍රකට සත්ව රූපය කුමක්ද?", "දිගු අං සහිත කඳු එළුවා (Ibex)", "සිංහල හංස පූට්ටුව", "දකුණු ඉන්දීය මොනරා", "අප්‍රිකානු සීබ්‍රා රුව", "සූසා ප්‍රදේශයේ පැරණි මැටි බඳුන්වල අතිශය ශෛලිගත දිගු අං සහිත කඳු එළුවාගේ රූප විශිෂ්ටය."),
        q("ලොව පැරණිතම සංගීත භාණ්ඩ හා කලා සාක්ෂි සමඟ හමු වී ඇති පුරාශිලා යුගයේ බටනළාව සාදා තිබුණේ කුමකින්ද?", "පක්ෂි අස්ථි සහ මැමත් ඇත්දත්", "පිත්තල සහ තඹ බට", "උණ බම්බු සහ රබර් පටි", "වීදුරු හා සෙරමික් නළ", "ජර්මනියේ ගුහාවලින් ගිජුලිහිණි අස්ථියකින් සෑදූ වසර 40,000ක් පැරණි බටනළා හමුවී ඇත."),
        q("ගුහා සිතුවම්වල 'රූප රාමු' (Frames) හෝ පැහැදිලි මායිම් දක්නට නොලැබීමට හේතුව කුමක්ද?", "පර්වත මතුපිටම සීමා රහිත කලා අවකාශය වීම", "රාමු ඇඳීමට අඟුරු කූරු මදි වීම", "කඩදාසි කොළ කුඩා වීම", "පසුකාලීන කලාකරුවන් රාමු මකා දැමීම", "නූතන චිත්‍ර මෙන් කොටු කළ රාමු නොතිබූ අතර මුළු ගල් බිත්තියම නිදහස් තලය විය."),
        q("පුරාශිලා ගුහා චිත්‍රවල දක්නට ලැබෙන 'කැන්ටබ්‍රියන්' ශෛලිය හා බැඳුණු ප්‍රධාන ලක්ෂණය කුමක්ද?", "වර්ණ භාවිතයෙන් සිරුරේ පරිමාව මතු කිරීම", "සියලු රූප චතුරස්‍ර ලෙස ඇඳීම", "අකුරු පමණක් ලියා තැබීම", "ජල සායම් විනිවිදභාවය යෙදීම", "ඇල්ටමීරා ඇතුළු කැන්ටබ්‍රියන් ගුහාවල බහු වර්ණ සෙවණැලි මගින් ජීවමාන පරිමාව දැක්වේ."),
        q("මධ්‍යශිලා (Mesolithic) යුගයේ සිතුවම්වල පුරාශිලා යුගයට වඩා කැපී පෙනෙන ප්‍රධාන තේමාත්මක වෙනස කුමක්ද?", "සමූහ මිනිස් ක්‍රියාකාරකම් හා දඩයම් දර්ශන බහුල වීම", "තනි සත්ව රූප පමණක් විශාලව ඇඳීම", "වීදුරු සහ සිමෙන්ති කැටයම් බිහිවීම", "පල්ලි සහ දේවාල සැලසුම් ඇඳීම", "මධ්‍යශිලා යුගයේදී කුඩා මිනිස් රූප සමූහ වශයෙන් දඩයමේ හා නැටුමේ යෙදෙන අයුරු බහුල විය."),
        q("සැලසුම්සහගත ජ්‍යාමිතික රටා අඩංගු වසර 73,000ක් පමණ පැරණි රතු ගුරුගල් කැබැල්ලක් හමුවූ දකුණු අප්‍රිකානු ගුහාව කුමක්ද?", "බ්ලොම්බොස් ගුහාව", "ටැසිලි ගුහාව", "නැස්කා ගුහාව", "කාල්ස්බැඩ් ගුහාව", "දකුණු අප්‍රිකාවේ බ්ලොම්බොස් ගුහාවෙන් හමු වූ රටා ඇඳි ගුරුගල් කැබැල්ල මානව කලාවේ ආදිතම සලකුණකි."),
        q("ප්‍රාග් ඓතිහාසික ගුහා චිත්‍රවල 'ශෛලිගතකරණය' (Stylization) යනුවෙන් අදහස් කරන්නේ කුමක්ද?", "සැබෑ ස්වරූපය සරල හා කලාත්මක හැඩයකට ගැනීම", "සතුන්ගේ සිරුර ඡායාරූප ලෙසම පිටපත් කිරීම", "වර්ණ සියල්ල සෝදා ඉවත් කිරීම", "චිත්‍ර මත රෙදි කැබලි ඇලවීම", "රූපවල අනවශ්‍ය විස්තර අත්හැර මූලික රේඛා හා හැඩතල පමණක් ඉස්මතු කිරීම ශෛලිගත කිරීමයි."),
        q("නවශිලා යුගයේ මිනිසුන් ඉදිකළ කුළුණු දෙකක් මත හරස් ගලක් තැබූ 'ඩොල්මන්' (Dolmen) නිර්මාණ යොදා ගත්තේ කුමකටද?", "ප්‍රාග් ඓතිහාසික සුසාන ස්මාරක ලෙස", "රාජකීය පාලම් ලෙස", "දිය ඇලි හරස් බැමි ලෙස", "වෙළඳ ගබඩා ගොඩනැගිලි ලෙස", "මහා ශිලා කුටි හෙවත් ඩොල්මන් යනු නවශිලා යුගයේ මියගිය අය වෙනුවෙන් තැනූ ස්මාරක වේ."),
        q("ලංකාවේ පාහියන්ගල හා බටදොඹලෙන කැණීම්වලින් හමු වූ ආදි මානවයාගේ කලාත්මක සාක්ෂි මොනවාද?", "සිදුරු කළ මුහුදු බෙල්ලන් හා සත්ව දත් පබළු", "රන් කැටයම් සහිත දළදා කරඬු", "තෙල් සායම් කැන්වස් චිත්‍ර රාමු", "රෝම සෙරමික් පිඟන් කැබලි", "බලංගොඩ මානවයා විසින් සැරසිලි ලෙස යොදා ගත් බෙලිකටු පබළු හා ගුරුගල් කැබලි හමු වී ඇත."),
        q("ආදි ගුහා සිතුවම්කරණයේදී 'පොලික්‍රෝම්' (Polychrome) චිත්‍ර ලෙස හඳුන්වන්නේ කුමන සිතුවම්ද?", "වර්ණ කිහිපයක් මිශ්‍ර කර ඇඳි සිතුවම්", "තනි කළු රේඛාවෙන් පමණක් ඇඳි සිතුවම්", "ගල හාරා පමණක් කෙටූ කැටයම්", "වර්ණ කිසිවක් නැති සුදු ලකුණු", "ඇල්ටමීරා වැනි ගුහාවල රතු, කහ, කළු හා දුඹුරු වර්ණ කිහිපයක් යොදා ඇඳි සිතුවම් මෙනමින් හැඳින්වේ."),
        q("මොනොක්‍රෝම් (Monochrome) ආදි ගුහා චිත්‍රයක් යන්නෙහි නිවැරදි අර්ථය කුමක්ද?", "තනි වර්ණයක විවිධ අගයන් පමණක් යෙදූ චිත්‍ර", "වර්ණ දොළහක්ම යෙදූ උත්සව චිත්‍ර", "දිලිසෙන වීදුරු කුඩු ඉසූ චිත්‍ර", "සෙවණැලි රහිත ජල සායම් චිත්‍ර", "ෂෝවේ ගුහාවේ මුල් චිත්‍ර මෙන් තනි කළු හෝ තනි රතු වර්ණයකින් පමණක් ඇඳි සිතුවම්ය."),
        q("ආදි ගුහා කලාකරුවන් ගුරුගල් කුඩු කෙළින්ම පර්වත මතුපිට ඇතිල්ලීමේ ක්‍රමය වර්තමාන කුමන මාධ්‍යයට සමානද?", "පැස්ටල් හෝ ක්‍රෙයොන් මාධ්‍යයට", "දියර ජල සායම් මාධ්‍යයට", "ලිනෝලියම් කැපුම් මාධ්‍යයට", "ඩිජිටල් ටැබ්ලට් මාධ්‍යයට", "වියළි ගුරුගල් හා අඟුරු කූරු ලෙස භාවිත කිරීම වියළි පැස්ටල් හා අඟුරු චිත්‍ර කලාවට සමානය."),
        q("චිත්‍ර කලා ඉතිහාසයේ ප්‍රථම 'වෘත්තීයමය සැලසුම්ගත සිතුවම්' බිහිවීම සනිටුහන් කළ කලාකරුවා ලෙස සැලකෙන්නේ කවුද?", "පුරාශිලා ගුහා චිත්‍ර ශිල්පියා", "බැරොක් යුගයේ ශිල්පියා", "නූතන ගෘහ නිර්මාණ ශිල්පියා", "පුනරුද යුගයේ මුද්‍රණකරුවා", "මානව ශිෂ්ටාචාරයේ මුල්ම දෘශ්‍ය සන්නිවේදන කලාව ආරම්භ කළේ ප්‍රාග් ඓතිහාසික ගුහා ශිල්පියාය."),
        q("ප්‍රංශයේ 'ට්‍රොයිස් ෆ්‍රේරෙස්' (Trois Frères) ගුහාවේ ඇති 'සෝසරර්' (The Sorcerer) චිත්‍රයෙන් නිරූපණය වන්නේ කුමක්ද?", "සත්ව හම් හා මුව අං පැළඳි මන්ත්‍රකරුවෙක්", "කුඹල් රෝදයේ වැඩ කරන කාන්තාවක්", "ඔරුවක් පදින ධීවරයෙක්", "රජෙකුගේ සිංහාසනාරූඪ උත්සවයක්", "මුව අං, බකමූණු ඇස් හා සත්ව වලිගයක් සහිත නටන මිනිස් රුව ශාමන් හෙවත් මන්ත්‍රකරු ලෙස හැඳින්වේ."),
        q("ප්‍රාග් ඓතිහාසික ගල් බිත්ති සිතුවම් වර්තමානයේ අධ්‍යයනය කිරීමෙන් පුරාවිද්‍යාඥයන්ට ලැබෙන ප්‍රධාන ප්‍රයෝජනය කුමක්ද?", "පුරාණ මානව සංස්කෘතිය හා වඳ වූ සතුන් හඳුනාගැනීම", "පතල් කැණීමේ ලාභය ගණනය කිරීම", "නවීන කෘත්‍රිම බුද්ධිය නිර්මාණය කිරීම", "අභ්‍යවකාශ යානා ඉන්ධන සෙවීම", "මැමත් හා ලොම් රයිනෝසිරස් වැනි වඳ වූ සතුන් හා ආදි මානව ජීවන රටාව හඳුනාගත හැක."),
        q("පුරාශිලා යුගයේ මුල් අවධියේ ගුහා සිතුවම් 'සිලුවට්' (Silhouette) ආකාරයට ඇඳීම යනු කුමක්ද?", "බාහිර රේඛාව තුළ තනි වර්ණයකින් පිරවීම", "පසුබිම කළු කර රූප සුදුවෙන් තැබීම", "වර්ණ සියල්ල කුඩා තිත් ලෙස තැබීම", "සෑම රූපයකටම කහ රාමුවක් ඇඳීම", "වස්තුවේ ඇතුළත විස්තර නොදක්වා තනි පැතලි ඡායාවක් ලෙස වර්ණ ගැන්වීම සිලුවට් ක්‍රමයයි."),
        q("භිම්බෙට්කා ලෙන් සංකීර්ණය යුනෙස්කෝ ලෝක උරුමයක් ලෙස ප්‍රකාශයට පත් කළේ කුමන වසරේදීද?", "2003 වර්ෂයේදී", "1948 වර්ෂයේදී", "1972 වර්ෂයේදී", "2020 වර්ෂයේදී", "2003 වර්ෂයේදී ඉන්දියාවේ භිම්බෙට්කා ප්‍රාග් ඓතිහාසික ගල් ලෙන් ලෝක උරුම ලැයිස්තුවට එක් විය."),
        q("ලොව පැරණිතම ගුහා චිත්‍ර ඇඳි පර්වත බිත්තිවල ඇති සුදු පැහැති කැල්සියම් තට්ටු චිත්‍ර ආරක්ෂා වීමට උපකාරී වූයේ කෙසේද?", "විනිවිද පෙනෙන ඛනිජ ස්ඵටික ආවරණයක් සෑදීමෙන්", "සෑම වසරකම වර්ණ අලුත් කිරීමෙන්", "වර්ණ සම්පූර්ණයෙන් ඉවත් කිරීමෙන්", "ගුහාවල තෙතමනය අධික ලෙස වැඩි කිරීමෙන්", "හුණුගල් ගුහාවල ජලයෙන් තැන්පත් වූ තුනී කැල්සයිට් තට්ටුව ස්වභාවික ආරක්ෂිත වැස්මක් විය."),
        q("ආදි ගුහා කලාවේ 'මැකරෝනි' (Finger Fluting) රේඛා යනුවෙන් හඳුන්වන්නේ කුමක්ද?", "මෘදු මැටි බිත්ති මත ඇඟිලිවලින් ඇඳි වක්‍ර රේඛා", "රතු තීන්තවලින් ඇඳි කෙළින් රේඛා", "මැටි බඳුන් මත තැබූ ලෝහ මුද්‍රා", "හුණුගල් කඩා දැමූ සිදුරු පෙළ", "තෙත් හුණුගල් පෘෂ්ඨය මත මිනිසුන් ඇඟිලිවලින් ඇඳි සර්පිලාකාර රේඛා මෙලෙස හැඳින්වේ."),
        q("ආදි මානවයා විසින් නිර්මාණය කරන ලද මුල්කාලීන කුඹල් මැටි ප්‍රතිමාවක් හමුවූ චෙක් ජනරජයේ අඩවිය කුමක්ද?", "ඩොල්නි වෙස්ටෝනිස්", "පැරිස් ගුහාව", "ඇතන්ස් ඇක්‍රොපොලිසය", "රෝම ෆෝරමය", "ඩොල්නි වෙස්ටෝනිස්හි වීනස් රුව වසර 29,000ක් පැරණි ලොව පැරණිතම පිළිස්සූ මැටි රුව වේ."),
        q("පුරාශිලා ගුහා සිතුවම්වල 'සංයුතිය' (Composition) පිළිබඳව නිවැරදි ප්‍රකාශය කුමක්ද?", "පැහැදිලි පාදක රේඛාවක් නොමැතිව ගල පුරා විසිරී ඇත", "සෑම චිත්‍රයක්ම පහළ සිට ඉහළට තීරුවල ඇඳ ඇත", "කේන්ද්‍රීය වෘත්තයක් තුළ පමණක් සීමා වී ඇත", "හරස් කොටු දැලක් ඇතුළත සමමිතිකව ඇඳ ඇත", "පොළොව හෝ අහස දක්වන පාදක රේඛාවක් නොමැතිව සතුන් අවකාශයේ පාවෙන සේ ඇඳ තිබීම විශේෂයකි."),
        q("නවශිලා යුගයේ සංස්කෘතික විප්ලවය කලා නිර්මාණවලට බලපෑ ප්‍රධාන ආකාරය කුමක්ද?", "ස්ථාවර නිවාස, මැටි කර්මාන්තය හා රෙදි විවීම ඇරඹීම", "ගල් ආයුධ සියල්ල භාවිතයෙන් ඉවත් කිරීම", "මුහුදු යාත්‍රා චිත්‍ර පමණක් ඇඳීම", "වීදුරු අහස්කූරු නිපදවීම", "දඩයමින් ගොවිතැනට හුරුවීම නිසා පොදු ජනාවාස කලා හා කර්මාන්ත දියුණු විය."),
        q("නවශිලා යුගයේදී මැටි භාජන වේගයෙන් හා සමමිතිකව තැනීමට හඳුන්වා දුන් ප්‍රධාන තාක්ෂණික උපකරණය කුමක්ද?", "සකපෝරුව හෙවත් කුඹල් රෝදය", "වාෂ්ප පීඩන යන්ත්‍රය", "ලෝහ වාත්තු අච්චුව", "දැව මුද්‍රණ බ්ලොක් එක", "සකපෝරුව (Potter's wheel) නිපදවීමත් සමඟ සමමිතික හා සියුම් මැටි බඳුන් බිහිවිය."),
        q("නෝර්වේ සහ රුසියාව වැනි උතුරු යුරෝපා ප්‍රදේශවල ඇති ප්‍රාග් ඓතිහාසික ගල් කෙටුම්වල බහුලව දැක්වෙන්නේ මොනවාද?", "පිනිමුවන්, තල්මසුන් සහ පැරණි ඔරු", "අලි ඇතුන් සහ පොල් ගස්", "ඔටුවන් සහ කාන්තාර වැලි කඳු", "සිංහයන් සහ මුව පොව්වන්", "උතුරු දේශගුණික පරිසරයට අනුව සීල් මසුන්, ඔරු සහ හිම සපත්තු කෙටුම් එහි දැකිය හැක."),
        q("ආදි ගුහා සිතුවම් පිළිබඳ අධ්‍යයනයේදී 'අභිචාරමය අර්ථය' තහවුරු වන ප්‍රධාන සාධකය කුමක්ද?", "සත්ව රූප මත හෙලි සහ ඊතල සලකුණු ඇඳ තිබීම", "ගුහාව ඉදිරිපිට වෙළඳපොළක් තිබීම", "චිත්‍ර යටින් මිල ගණන් සටහන් කර තිබීම", "ගුහා ඇතුළත පාසල් මේස තබා තිබීම", "ඇතැම් සත්ව රූප මත හෙලි පහරවල් වැදුණු ආකාරයේ රේඛා ඇඳ තිබීම දඩයම් අභිචාර පෙන්වයි."),
        q("ලැස්කෝ ගුහාවේ 'චීන අශ්වයා' (Chinese Horse) නමින් හඳුන්වන චිත්‍රයට එම නම ලැබී ඇත්තේ ඇයි?", "පැරණි චීන තීන්ත චිත්‍රවල අශ්ව රූපවලට ඇති සමානකම නිසා", "චීන කලාකරුවෙකු ප්‍රංශයට ගොස් ඇඳි නිසා", "අශ්වයාගේ ඇඟේ චීන අකුරු ලියා ඇති නිසා", "චීන සේද රෙදි කැබැල්ලක ඇඳ ඇති නිසා", "කෙටි පාද සහ පිරුණු සිරුර සහිත එම අශ්ව රුව චීන ටෑං යුගයේ අශ්ව රූපවලට සමාන වේ."),
        q("ඉතාලියේ වැල්කැමොනිකා (Valcamonica) ප්‍රදේශය යුනෙස්කෝ උරුමයක් වී ඇත්තේ කුමන ප්‍රාග් ඓතිහාසික කලා අංගය නිසාද?", "ලක්ෂ ගණනක් වූ පර්වත ශිලා කෙටුම් නිසා", "විශාල රන් ආලේපිත ප්‍රතිමා නිසා", "පැරණිතම තෙල් සායම් කැන්වස් නිසා", "පුරාණ වීදුරු කැඩපත් නිසා", "වැල්කැමොනිකා නිම්නයේ ලෝහ යුගය දක්වා දිවෙන දහස් ගණන් පර්වත කෙටුම් සංරක්ෂිතය."),
        q("ප්‍රාග් ඓතිහාසික යුගයේදී තඹ සහ ටින් මිශ්‍ර කර ලෝකඩ නිපදවීම ඇරඹුණු යුගයේ කලා නිර්මාණවල විශේෂත්වය කුමක්ද?", "සියුම් ලෝහ ආයුධ හා සත්ව මූර්ති වාත්තු කිරීම", "කැන්වස් මත ඇක්‍රිලික් චිත්‍ර ඇඳීම", "වීදුරු කැටයම් මාලිගා සෑදීම", "සිමෙන්ති ප්‍රතිමා කර්මාන්තය ඇරඹීම", "ලෝකඩ යුගයේදී ඉටි මගින් වාත්තු කිරීමේ තාක්ෂණය (Lost-wax) දියුණු විය."),
        q("ආජන්ටිනාවේ පිහිටි 'සියෙවා ඩි ලාස් මැනෝස්' (Cueva de las Manos) ගුහාව ප්‍රකට වී ඇත්තේ කුමකින්ද?", "වර්ණවත් මිනිස් අත් සලකුණු සිය ගණනකින්", "රන්වන් හංස රූප දහසකින්", "පිළිස්සූ මැටි වෙස්මුහුණු වලින්", "කැටයම් කළ දැව කුළුණු වලින්", "පැටගෝනියා කලාපයේ පිහිටි මෙම ගුහාවේ වම් අත් ස්ටෙන්සිල් සලකුණු විශාල සංඛ්‍යාවක් ඇත."),
        q("ප්‍රාග් ඓතිහාසික යුගයේ චිත්‍රවල පසුබිම් දර්ශන (Landscapes) ඇඳීම දක්නට නොලැබෙන්නේ ඇයි?", "ප්‍රධාන අවධානය සත්වයා හෝ අභිචාරමය අරමුණ වෙත යොමු වූ බැවින්", "කොළ සහ නිල් ගස්වැල් පරිසරයේ නොතිබූ බැවින්", "ගල්වල ඉඩ මදිවීම නිසා පසුබිම කැපූ බැවින්", "පසුබිම් ඇඳීම රාජ්‍ය නීතියෙන් තහනම් වූ බැවින්", "ගස් වැල් හෝ කඳු වෙනුවට දඩයමට අදාළ සත්ව රූපයම පමණක් මූලික විය."),
        q("ඕස්ට්‍රියාවේ විලෙන්ඩෝෆ්හි වීනස් රුවෙහි මුහුණේ විස්තර කැටයම් නොකර තිබීමෙන් කලා විචාරකයන් ගම්‍ය කරන්නේ කුමක්ද?", "පුද්ගලික අනන්‍යතාවකට වඩා පොදු සශ්‍රීකත්ව සංකේතයක් බව", "කැටයම්කරුට මුහුණ ඇඳීම අමතක වූ බව", "මුහුණ කොටස කාලයත් සමඟ කැඩී ගිය බව", "රුව සම්පූර්ණ කිරීමට පෙර ගල ඉරි තැළුණු බව", "මුහුණ රහිතව හිස වටා ගෙතූ රටා පමණක් යෙදීම විශ්වීය මාතෘ සංකල්පය අවධාරණය කරයි."),
        q("ස්පාඤ්ඤයේ ඇල්ටමීරා ගුහාවේ බයිසන් ගව රූප හඳුන්වනු ලබන විශේෂ කලාත්මක යෙදුම කුමක්ද?", "පුරාශිලා යුගයේ සිස්ටයින් දෙව්මැදුර", "යුරෝපයේ නූතන කෞතුකාගාරය", "පැරණි ලෝකයේ ඇක්‍රොපොලිසය", "මධ්‍යකාලීන රන් පුස්තකාලය", "වහලයේ ඇති අතිශය චමත්කාරජනක බහු වර්ණ සිතුවම් නිසා ඇල්ටමීරාව මෙලෙස හැඳින්වේ."),
        q("ආදි ගුහා සිතුවම් හා ශ්‍රී ලංකාවේ බිතුසිතුවම් අතර භාවිත කළ වර්ණක අතින් ඇති ප්‍රධාන සමානකම කුමක්ද?", "ස්වභාවික ගුරුගල්, අඟුරු සහ කිරිමැටි භාවිතය", "කෘත්‍රිම ඇනිලයින් රසායනික ඩයි භාවිතය", "තෙල් මිශ්‍ර කෘත්‍රිම සායම් නළ භාවිතය", "රසදිය සල්ෆේට් පමණක් භාවිතය", "ලෝකයේ ආදි ගුහා චිත්‍රවල මෙන්ම සීගිරි හා කඳුරට සිතුවම්වලද ස්වභාවික ඛනිජ වර්ණක යොදා ගැනිණි."),
        q("ලෝකයේ ඇති 'ගුහා චිත්‍ර' (Cave Paintings) සහ 'ශිලා ලේඛන අවරණ චිත්‍ර' (Rock Shelter Art) අතර වෙනස කුමක්ද?", "ගුහා චිත්‍ර ගැඹුරු අඳුරු තැන්වලද අවරණ චිත්‍ර එළිමහන් ආලෝකයේද ඇත", "ගුහා චිත්‍ර කඩදාසි මතද අවරණ චිත්‍ර රෙදි මතද ඇඳ ඇත", "ගුහා චිත්‍ර තෙල් සායම්ද අවරණ චිත්‍ර ඇක්‍රිලික්ද වේ", "අවරණ චිත්‍ර සියල්ල නූතන ශිල්පීන්ගේ නිර්මාණය", "ගැඹුරු ගුහාවල පහන් එළියෙන්ද ගල් පියස්ස යට චිත්‍ර ස්වභාවික හිරු එළියෙන්ද ඇඳ ඇත."),
        q("අනුකරණ කලාව හෙවත් 'ස්වභාවධර්මය අනුකරණය කිරීම' (Naturalism) ප්‍රාග් ඓතිහාසික කුමන නිර්මාණවල වඩාත් ඉස්මතු වේද?", "ඇල්ටමීරා හා ලැස්කෝ සත්ව සිතුවම්වල", "නවශිලා මැටි බඳුන්වල කතිර රටාවල", "ස්ටෝන්හෙන්ජ්හි සිරස් ගල් කුළුණුවල", "ඩොල්මන් සුසාන ගල් පුවරුවල", "පුරාශිලා ගුහා සත්ව රූප නවශිලා ජ්‍යාමිතික රටාවලට වඩා අතිශයින් ස්වභාවික ලක්ෂණ දරයි."),
        q("ප්‍රාග් ඓතිහාසික යුගයේ චිත්‍ර අඳින ලද ඇතැම් ශිලා මතුපිට පිළිස්සී ගිය අඟුරු සලකුණු හමුවීමෙන් කුමක් හෙළි වේද?", "ගල් බිත්තියට ඉතා ආසන්නව පන්දම් දැල්වූ බව", "ගුහාව ගිනි කන්දකින් වැසී ගිය බව", "සිතුවම් උදුනක දමා පුළුස්සා ඇති බව", "ලෝහ උණු කිරීමේ කම්මල් තිබූ බව", "අඳුරු ගුහා තුළ චිත්‍ර ඇඳීමේදී පන්දම් හා තෙල් පහන් භාවිත කළ බවට අඟුරු සලකුණු සාක්ෂි සපයයි."),
        q("කලා විචාරයේදී 'ප්‍රාග් ඓතිහාසික කලාවේ වැදගත්කම' ලෙස සලකනු ලබන ප්‍රධානතම කරුණ කුමක්ද?", "මානවයාගේ නිර්මාණශීලී චින්තනයේ සහ දෘශ්‍ය සන්නිවේදනයේ ආරම්භය වීම", "ලෝකයේ වඩාත්ම මිල අධික කැන්වස් චිත්‍ර නිපදවීම", "පැරණි රජවරුන්ගේ බදු ගිණුම් පවත්වාගෙන යාම", "නූතන ඡායාරූප ශිල්පයේ කැමරා කාච නිපදවීම", "ලේඛන කලාවට පෙර සිටම මානවයා රූප මගින් අදහස් පළ කළ බව මෙමගින් තහවුරු වේ.")
    )
}
